/**
 * Lines the document renderer silently removes (legacy model boilerplate / promotional copy).
 * Shared so that the approved clause text can be tested against it: any approved wording that
 * contains one of these phrases would vanish from the rendered form without any error.
 */
export const STRIPPED_PHRASES = [
  "this form is legally binding per imc",
  "aadhaar data is masked per the aadhaar act",
  "blanket consent is void in india",
  "generation timestamp:",
  "icmr national ethical guidelines",
  "generated by consentgen",
  "powered by consentgen",
  "consentgen.in",
  "consentgen platform",
] as const;

export function isStrippedLine(line: string): boolean {
  const lower = line.toLowerCase().trim();
  if (STRIPPED_PHRASES.some((p) => lower.includes(p))) return true;
  return lower.startsWith("consent id:") && (lower.includes("srpx") || lower.includes("auto-generated"));
}
